#include "key_custody.h"
#include <aclapi.h>
#include <bcrypt.h>
#include <iostream>
#include <ncrypt.h>
#include <sddl.h>
#include <vector>
#pragma comment(lib,"ncrypt.lib")
#pragma comment(lib,"advapi32.lib")
namespace {
struct Target{const wchar_t*key;const wchar_t*account;};
constexpr Target targets[]={{L"AegisStellarCustodian-Issuer-P256-v1",L"NT SERVICE\\AegisStellarCustodian"},{L"AegisStellarExecutionBroker-Attestation-P256-v1",L"NT SERVICE\\AegisStellarExecutionBroker"}};
const Target*Find(const wchar_t*name){for(const auto&t:targets)if(wcscmp(t.key,name)==0)return&t;return nullptr;}
bool SidFor(const wchar_t*account,std::vector<BYTE>&sid){DWORD sb=0,db=0;SID_NAME_USE use{};LookupAccountNameW(nullptr,account,nullptr,&sb,nullptr,&db,&use);if(GetLastError()!=ERROR_INSUFFICIENT_BUFFER)return false;sid.resize(sb);std::vector<wchar_t>domain(db);return LookupAccountNameW(nullptr,account,sid.data(),&sb,domain.data(),&db,&use)!=FALSE;}
bool ExactDescriptor(const wchar_t*account,PSECURITY_DESCRIPTOR*result){std::vector<BYTE>system(SECURITY_MAX_SID_SIZE),service;DWORD bytes=static_cast<DWORD>(system.size());if(!CreateWellKnownSid(WinLocalSystemSid,nullptr,system.data(),&bytes)||!SidFor(account,service))return false;EXPLICIT_ACCESSW entries[2]{};for(auto&e:entries){e.grfAccessPermissions=GENERIC_ALL;e.grfAccessMode=SET_ACCESS;e.grfInheritance=NO_INHERITANCE;e.Trustee.TrusteeForm=TRUSTEE_IS_SID;e.Trustee.TrusteeType=TRUSTEE_IS_USER;}entries[0].Trustee.ptstrName=reinterpret_cast<LPWSTR>(system.data());entries[1].Trustee.ptstrName=reinterpret_cast<LPWSTR>(service.data());PACL acl{};if(SetEntriesInAclW(2,entries,nullptr,&acl)!=ERROR_SUCCESS)return false;SECURITY_DESCRIPTOR absolute{};bool ok=InitializeSecurityDescriptor(&absolute,SECURITY_DESCRIPTOR_REVISION)&&SetSecurityDescriptorOwner(&absolute,system.data(),FALSE)&&SetSecurityDescriptorDacl(&absolute,TRUE,acl,FALSE);DWORD relativeBytes=0;if(ok)MakeSelfRelativeSD(&absolute,nullptr,&relativeBytes);auto relative=static_cast<PSECURITY_DESCRIPTOR>(LocalAlloc(LPTR,relativeBytes));ok=ok&&relative&&MakeSelfRelativeSD(&absolute,relative,&relativeBytes);LocalFree(acl);if(!ok){if(relative)LocalFree(relative);return false;}*result=relative;return true;}
}
int wmain(int argc,wchar_t**argv){if(argc!=3&&argc!=4){std::wcerr<<L"usage: provision-keys --key-name <approved-name> [--allow-software-custody]\n";return 64;}if(wcscmp(argv[1],L"--key-name")!=0)return 64;const Target*target=Find(argv[2]);if(!target)return 65;const bool software=argc==4&&wcscmp(argv[3],L"--allow-software-custody")==0;if(argc==4&&!software)return 64;const wchar_t*providerName=software?MS_KEY_STORAGE_PROVIDER:MS_PLATFORM_CRYPTO_PROVIDER;NCRYPT_PROV_HANDLE provider{};SECURITY_STATUS status=NCryptOpenStorageProvider(&provider,providerName,0);if(status!=ERROR_SUCCESS)return 66;NCRYPT_KEY_HANDLE existing{};if(NCryptOpenKey(provider,&existing,target->key,0,NCRYPT_MACHINE_KEY_FLAG)==ERROR_SUCCESS){NCryptFreeObject(existing);NCryptFreeObject(provider);std::wcerr<<L"refusing to overwrite existing approved key\n";return 67;}NCRYPT_KEY_HANDLE key{};PSECURITY_DESCRIPTOR descriptor{};if(!ExactDescriptor(target->account,&descriptor)){NCryptFreeObject(provider);return 68;}status=NCryptCreatePersistedKey(provider,&key,NCRYPT_ECDSA_P256_ALGORITHM,target->key,0,NCRYPT_MACHINE_KEY_FLAG);DWORD exportPolicy=0;if(status==ERROR_SUCCESS)status=NCryptSetProperty(key,NCRYPT_EXPORT_POLICY_PROPERTY,reinterpret_cast<PBYTE>(&exportPolicy),sizeof(exportPolicy),NCRYPT_PERSIST_FLAG);if(status==ERROR_SUCCESS)status=NCryptSetProperty(key,NCRYPT_SECURITY_DESCR_PROPERTY,reinterpret_cast<PBYTE>(descriptor),GetSecurityDescriptorLength(descriptor),NCRYPT_PERSIST_FLAG|OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION);if(status==ERROR_SUCCESS)status=NCryptFinalizeKey(key,0);LocalFree(descriptor);if(status!=ERROR_SUCCESS){if(key)NCryptDeleteKey(key,0);NCryptFreeObject(provider);return 69;}NCryptFreeObject(key);NCryptFreeObject(provider);stellar::service::ProvisionedKeyEvidence evidence{};NCRYPT_KEY_HANDLE reopened{};status=stellar::service::OpenAndVerifyProvisionedP256Key(providerName,target->key,L"",target->account,software,&reopened,evidence);if(status!=ERROR_SUCCESS){NCRYPT_PROV_HANDLE cleanupProvider{};NCRYPT_KEY_HANDLE cleanup{};if(NCryptOpenStorageProvider(&cleanupProvider,providerName,0)==ERROR_SUCCESS&&NCryptOpenKey(cleanupProvider,&cleanup,target->key,0,NCRYPT_MACHINE_KEY_FLAG)==ERROR_SUCCESS)NCryptDeleteKey(cleanup,0);if(cleanupProvider)NCryptFreeObject(cleanupProvider);return 70;}NCryptFreeObject(reopened);std::wcout<<L"{\"kid\":\""<<evidence.kid<<L"\",\"keyName\":\""<<target->key<<L"\",\"privateExportRefused\":true,\"provider\":\""<<providerName<<L"\",\"schema\":\"stellar.t7d-d3-key-provision-evidence/v0.1\",\"serviceAccount\":\""<<target->account<<L"\"}\n";return 0;}
